window.QA_ITEMS = [{"id":1,"q":"술 문제는 의지가 약해서 생기는 것인가, 아니면 병인가?","a":"알코올 사용장애는 의지의 약함만으로 설명되는 문제가 아니라 뇌의 보상체계와 행동 조절이 함께 변하는 치료 대상입니다. 병이라는 설명은 책임을 없애기 위한 말이 아니라 비난보다 치료와 관리를 선택하기 위한 기준입니다.","cat":"알코올","tags":["알코올","치료·약물"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":2,"q":"어느 정도 마시면 알코올 중독으로 진단되는가?","a":"진단은 술의 양 하나로 정하지 않습니다. 최근 12개월 동안 조절 실패, 갈망, 내성·금단, 역할 손상, 위험한 음주 등 여러 항목을 종합해 전문가가 평가합니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":3,"q":"술을 끊었는데도 자꾸 술 생각이 난다. 갈망이란 무엇인가?","a":"갈망은 술을 사용하고 싶은 강한 욕구로, 금단이 끝난 뒤에도 이어질 수 있습니다. 참는 힘만 키우기보다 촉발 상황과 감정을 알아차리고 피하거나 다른 행동으로 넘기는 대처가 중요합니다.","cat":"알코올","tags":["알코올","갈망·재발"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":4,"q":"여성은 남성보다 술에 더 취약한가?","a":"여성은 같은 양에도 혈중알코올농도와 신체 부담이 더 커질 수 있고, 치료 현장에서는 문제가 더 빠르게 진행되는 양상이 관찰되기도 합니다. 다만 개인차가 크므로 성별만으로 단정하지 않고 개별 평가가 필요합니다.","cat":"알코올","tags":["알코올","치료·약물"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":5,"q":"여성의 술 문제는 왜 더 늦게 발견되고, 왜 숨기게 되는가?","a":"여성의 음주에는 사회적 낙인과 수치심이 더 강하게 작용해 혼자 마시거나 문제를 숨기기 쉽습니다. 비난과 추궁보다 안전한 상담 환경과 여성 친화적인 치료·모임 연결이 중요합니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":6,"q":"배우자가 술 문제를 인정하지 않는다. 가족이 가장 먼저 알아야 할 것은 무엇인가?","a":"부인과 저항은 치료 초기에 흔합니다. 가족이 병명을 인정시키는 논쟁을 벌이기보다 구체적인 사건과 걱정을 말하고, 가족 자신부터 상담과 교육에 연결되는 편이 더 현실적입니다.","cat":"알코올","tags":["알코올","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":7,"q":"공동의존이라는 말을 들었다. 가족이 병을 키운다는 뜻인가?","a":"공동의존은 가족을 탓하는 말이 아니라 오랫동안 상대의 음주를 중심으로 살며 자기 감정과 욕구를 잃어버린 상태를 설명하는 개념입니다. 가족도 별도의 회복과 지지가 필요합니다.","cat":"알코올","tags":["알코올","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":8,"q":"술을 숨기고, 빚을 갚아주고, 뒤처리를 해주는 것이 도움이 되는가?","a":"안전을 지키는 개입과 음주의 결과를 대신 떠안는 뒤처리는 구분해야 합니다. 반복적인 수습은 당사자가 문제의 결과를 경험할 기회를 줄일 수 있으므로, 안전을 제외한 부분은 상담자와 경계를 정하는 것이 좋습니다.","cat":"알코올","tags":["알코올","재정·법률"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":9,"q":"알아넌 같은 가족 모임이 정말 도움이 되는가?","a":"비슷한 경험을 한 가족과 연결되는 것은 고립을 줄이고 대처방식을 바꾸는 데 도움이 될 수 있습니다. 처음에는 말하지 않고 듣기만 해도 되며, 여러 모임을 경험해 자신에게 맞는 곳을 찾을 수 있습니다.","cat":"알코올","tags":["알코올","모임·동료","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":10,"q":"치료에는 어떤 방법들이 있고, 무엇이 효과가 있다고 검증되었는가?","a":"동기강화치료, 인지행동치료, 12단계 촉진, 약물치료와 자조모임 등 여러 근거 기반 접근이 있습니다. 한 가지가 다른 것을 대신하기보다 개인 상태에 맞게 병행하는 것이 일반적입니다.","cat":"알코올","tags":["알코올","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":11,"q":"치료를 마치고 나온 뒤 언제가 가장 위험한가?","a":"퇴원이나 집중치료 직후 몇 달은 생활환경으로 다시 돌아가며 재발 위험이 커지는 시기입니다. 첫 외래, 모임, 지역사회 지원을 퇴원 전에 정해 치료 공백을 줄이는 것이 중요합니다.","cat":"알코올","tags":["알코올","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":12,"q":"재발했다. 지금까지의 치료가 모두 실패한 것인가?","a":"재발은 치료가 무효였다는 뜻이 아닙니다. 안전을 먼저 확인하고 가능한 한 빨리 치료와 모임으로 돌아가 무엇이 촉발했는지 복기해 다음 계획을 수정하는 것이 중요합니다.","cat":"알코올","tags":["알코올","갈망·재발","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":13,"q":"어떤 상황에서 재발이 잘 일어나며, 미리 알 수 있는 신호가 있는가?","a":"불안·우울·분노·외로움, 불면, 술을 미화하는 생각, 모임 회피와 같은 변화가 재발 전 신호가 될 수 있습니다. 첫 잔보다 앞서 나타나는 신호를 알아차리면 개입할 시간이 생깁니다.","cat":"알코올","tags":["알코올","갈망·재발"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":14,"q":"여성의 재발은 남성과 무엇이 다른가?","a":"여성의 재발은 관계 갈등, 정서적 상처, 수면 문제와 낙인 등이 복합적으로 얽히는 경우가 많습니다. 성별에 따른 평균 차이보다 각 개인의 촉발요인을 구체적으로 파악하는 것이 더 중요합니다.","cat":"알코올","tags":["알코올","갈망·재발"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":15,"q":"술 냄새가 나는지 확인하고 추궁하는 것이 단주에 도움이 되는가?","a":"일상적인 감시와 추궁은 숨김과 갈등을 키울 수 있습니다. 안전과 치료 참여처럼 꼭 확인할 항목은 미리 합의하고, 음주 판별 자체를 가족의 상시 감시로 만들지 않는 것이 좋습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":16,"q":"재발한 것을 알았을 때 가족은 어떻게 반응해야 하는가?","a":"순서는 안전 확인, 술이 깬 뒤 사실 중심의 대화, 치료·모임 복귀 지원, 가족 자신의 지지체계 가동입니다. 취한 상태에서의 설교나 즉흥적인 큰 결정은 피하는 것이 좋습니다.","cat":"알코올","tags":["알코올","갈망·재발","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":17,"q":"부모의 술 문제가 아이에게 어떤 영향을 주며, 아이를 어떻게 도와야 하는가?","a":"아이에게 불안, 자책, 과도한 책임감이 남을 수 있습니다. 아이의 나이에 맞게 '이것은 어른의 병이고 네 잘못이 아니다'라고 설명하고, 안전하게 말할 수 있는 어른과 상담 자원을 연결해야 합니다.","cat":"알코올","tags":["알코올","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":18,"q":"알코올 중독은 대물림되는가? 우리 아이도 그렇게 되는 것 아닌가?","a":"가족력은 위험을 높일 수 있지만 운명은 아닙니다. 안정된 관계, 우울·불안의 조기 발견, 감정을 말할 수 있는 환경과 조기 개입이 위험 경로를 바꾸는 데 도움이 됩니다.","cat":"알코올","tags":["알코올","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":19,"q":"잔소리도 설득도 소용이 없다. 무엇이 환자의 변화동기를 높이는가?","a":"압박보다 스스로 변화 이유를 말하게 돕는 대화, 가족의 지지와 긍정적인 대처가 변화동기에 더 도움이 됩니다. 동기는 고정된 것이 아니라 오르내리므로 올라오는 순간을 치료 연결로 이어가는 것이 중요합니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":20,"q":"회복에는 얼마나 걸리며, 언제쯤 '나았다'고 할 수 있는가?","a":"회복은 어느 날 끝나는 사건보다 지속적으로 관리되는 과정에 가깝습니다. 몸, 감정, 관계는 서로 다른 속도로 회복되므로 단주 기간만으로 '완치'를 판단하기보다 생활 기능과 지지체계를 함께 봐야 합니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":21,"q":"여성은 같은 양을 마셔도 왜 더 취하고 몸이 더 상하는가?","a":"체수분과 알코올 대사 차이 때문에 같은 양에서도 여성의 혈중알코올농도가 더 높게 올라갈 수 있습니다. 적게 마신다는 이유만으로 신체 위험을 낮게 보지 않는 것이 중요합니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":22,"q":"여성은 금단증상도 더 심한가? 가족력이 있으면 어떻게 되는가?","a":"일부 연구에서 여성 환자에게 심한 금단과 가족력이 더 자주 관찰되었습니다. 손 떨림, 식은땀, 환각, 경련 같은 금단이 의심되면 양과 성별을 따지기보다 의료기관에서 평가받아야 합니다.","cat":"알코올","tags":["알코올","몸·안전","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":23,"q":"임신 중에 마신 술이 아이에게 정말 영향을 주는가? 안전한 양은 있는가?","a":"임신 중 안전하다고 확인된 음주량은 없습니다. 이미 마셨다면 자책하거나 숨기기보다 산부인과와 중독 치료진에게 사실대로 알리고 필요한 추적과 지원을 받는 것이 중요합니다.","cat":"알코올","tags":["알코올","가족·자녀","몸·안전"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":24,"q":"우울하고 잠이 오지 않아서 마신다. 술이 정말 도움이 되는가?","a":"술은 잠드는 느낌을 줄 수 있지만 수면의 질과 우울을 악화시키는 악순환을 만들 수 있습니다. 불면과 우울은 술과 별개로 치료 가능한 문제이므로 의료진에게 함께 알려야 합니다.","cat":"알코올","tags":["알코올","몸·생활","마음·정서"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":25,"q":"과거에 겪은 폭력이나 학대 때문에 마신다. 그 상처는 어떻게 다뤄야 하는가?","a":"외상은 음주와 재발의 촉발요인이 될 수 있습니다. 안전과 사용 중단을 먼저 안정시키면서, 준비된 시점에 외상 경험을 다룰 수 있는 전문가와 순서를 정하는 것이 좋습니다.","cat":"알코올","tags":["알코올","몸·안전"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":26,"q":"여성만을 위한 치료 프로그램이 따로 있는가? 효과가 있는가?","a":"여성의 관계·정서·양육·낙인 경험을 반영한 여성 중심 프로그램이 있으며 우울과 단주효능감 개선이 보고되어 있습니다. 혼성 집단이 불편하다면 여성 프로그램이나 여성 친화적 자원을 문의할 수 있습니다.","cat":"알코올","tags":["알코올","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":27,"q":"완전히 끊어야만 하는가? 조절해서 조금씩 마시는 것은 안 되는가?","a":"알코올 사용장애로 진단된 경우에는 조절음주보다 단주가 더 안정적인 목표로 권고되는 경우가 많습니다. 아직 위험음주 단계인지 사용장애인지에 따라 목표가 달라질 수 있으므로 전문가 평가가 필요합니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":28,"q":"술을 마시면 기억이 끊긴다. 블랙아웃은 위험한 신호인가?","a":"블랙아웃은 취한 동안 기억이 저장되지 않는 상태로, 사고·폭력·인지 손상 위험과 연결될 수 있습니다. 반복된다면 단순한 술자리 해프닝으로 넘기지 말고 평가와 치료를 시작할 이유가 됩니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":29,"q":"회복한 여성이 다른 여성을 돕는 일은 어떤 의미가 있는가?","a":"동료지원은 도움받는 사람뿐 아니라 돕는 회복자에게도 의미와 자기효능감을 줄 수 있습니다. 다만 자신의 회복이 안정되어 있고 활동 부담을 나눌 수 있는 지지체계가 함께 있어야 합니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":30,"q":"퇴원한 뒤에는 어디에서 도움을 받을 수 있는가?","a":"병원 외래, 중독관리통합지원센터, 자조모임과 가족모임을 함께 연결해 두는 것이 좋습니다. 첫 외래 날짜, 모임 일정, 위기 때 연락할 곳을 퇴원 전에 정하면 치료 공백을 줄일 수 있습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":31,"q":"남편의 술 문제로 결혼생활이 힘들다. 이것이 나만 겪는 일인가?","a":"술 문제가 있는 가정에서 낮은 결혼만족도, 갈등과 부정정서는 흔하게 보고됩니다. 혼자 버티는 문제가 아니라 가족 상담과 가족모임에서 다룰 수 있는 회복 과제입니다.","cat":"알코올","tags":["알코올","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":32,"q":"친정 아버지도 술 문제였는데 남편도 그렇다. 왜 이런 일이 반복되는가?","a":"성장기 관계 경험이 이후의 관계 선택과 대처방식에 영향을 줄 수 있습니다. 반복을 운명이나 잘못으로 보기보다 상담과 공동체를 통해 익숙한 관계 패턴을 알아차리고 다른 선택을 연습할 수 있습니다.","cat":"알코올","tags":["알코올","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":33,"q":"남편을 입원시키는 것이 맞는 결정인가? 죄책감이 든다.","a":"입원 여부는 죄책감보다 안전, 금단, 자살·폭력 위험, 외래치료 실패 같은 상태를 기준으로 의료진과 판단해야 합니다. 결정과 이후 계획을 가족 혼자 떠안지 않는 것이 중요합니다.","cat":"알코올","tags":["알코올","치료","가족·관계","마음·정서"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":34,"q":"남편이 술을 끊으면 우리 부부 관계는 저절로 좋아지는가?","a":"단주는 관계 회복의 출발점이지 자동으로 관계를 복원시키지는 않습니다. 오래 굳어진 추궁·방어와 상처를 다루려면 부부·가족 상담과 새로운 의사소통 연습이 필요할 수 있습니다.","cat":"알코올","tags":["알코올","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":35,"q":"가족인 나도 상담을 받아야 하는가? 아픈 사람은 남편인데.","a":"가족은 환자의 보조자가 아니라 오랜 긴장과 소진의 영향을 받은 당사자이기도 합니다. 가족 상담은 환자를 더 잘 통제하기 위한 교육보다 가족 자신의 회복과 경계를 돕는 과정입니다.","cat":"알코올","tags":["알코올","치료","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":36,"q":"이혼을 생각하고 있다. 회복을 포기하는 것인가?","a":"이혼이나 분리를 고민한다고 해서 회복을 포기하는 것은 아닙니다. 안전을 먼저 확보하고 자신의 상태를 회복한 뒤 충분한 정보와 상담 속에서 결정하되, 폭력이 있다면 보호와 분리가 우선일 수 있습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":37,"q":"남편의 술 문제로 아이에게 화를 내게 된다. 어떻게 해야 하는가?","a":"만성 긴장 속에서는 감정이 아이에게 향하기 쉽습니다. 화를 낸 뒤 아이에게 잘못이 없음을 분명히 말해 관계를 복구하고, 부모교육과 가족 상담을 통해 자신의 소진도 함께 다루는 것이 필요합니다.","cat":"알코올","tags":["알코올","가족·관계","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":38,"q":"가족이 술 문제를 대하는 방식에 따라 결과가 달라지는가?","a":"감시와 통제보다 사실 중심 대화, 치료 연결, 일관된 경계와 지지가 변화동기에 더 도움이 될 수 있습니다. 가족교육은 환자를 관리하는 기술이 아니라 도움이 되는 대처와 소진을 구분하는 과정입니다.","cat":"알코올","tags":["알코올","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":39,"q":"오랫동안 참고 살았더니 내가 누구인지 모르겠다.","a":"오랫동안 상대의 문제를 중심으로 살면 자기 욕구와 정체감이 흐려질 수 있습니다. 상담·가족모임과 함께 예전에 좋아하던 일과 자신의 시간을 조금씩 되찾는 것이 가족 회복의 일부입니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":40,"q":"가족은 회복 과정에서 무엇을 기대할 수 있는가?","a":"환자의 단주뿐 아니라 가족 자신의 성장, 경계 회복, 관계의 재구성을 기대할 수 있습니다. 과거 그대로로 돌아가는 것보다 새로운 방식의 관계를 만들어가는 과정으로 보는 편이 현실적입니다.","cat":"알코올","tags":["알코올","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":41,"q":"술을 갑자기 끊으면 위험하다는데, 금단증상은 어떤 것인가?","a":"손 떨림, 식은땀, 불안, 불면, 구토, 혈압·맥박 상승이 나타날 수 있고 일부는 환각·경련·심한 혼란으로 진행할 수 있습니다. 심한 증상이나 과거 섬망·경련 경험이 있으면 집에서 버티지 말고 119 또는 의료기관에 연결해야 합니다.","cat":"알코올","tags":["알코올","몸·안전"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":42,"q":"잘 먹지 않고 술만 마신다. 영양 문제도 생기는가?","a":"만성 음주는 영양결핍, 특히 티아민 부족으로 심각한 신경학적 문제를 만들 수 있습니다. 비틀거림, 의식 혼란, 눈 움직임 이상이 보이면 즉시 진료가 필요합니다.","cat":"알코올","tags":["알코올","몸·생활"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":43,"q":"술 때문에 머리가 나빠졌다는 말이 사실인가?","a":"만성 음주는 기억력·주의력·판단력 같은 인지기능을 떨어뜨릴 수 있습니다. 술을 마시지 않은 날에도 반복적인 기억 문제나 일상 기능 저하가 이어지면 신경인지 평가를 받아보는 것이 좋습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":44,"q":"술 마시고 죽고 싶다는 말을 자주 한다. 진심인가, 넘겨도 되는가?","a":"취중 자살 언급도 실제 위험으로 이어질 수 있어 넘기면 안 됩니다. 직접 안전을 확인하고, 급한 위험이면 109·119·112와 응급의료체계에 즉시 연결해야 합니다.","cat":"알코올","tags":["알코올","몸·안전"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":45,"q":"왜 술 문제가 있으면 자살 위험이 높아지는가?","a":"만취 상태의 충동성·판단력 저하에 우울, 실직, 관계붕괴와 고립이 겹치면 위험이 커질 수 있습니다. 특히 재발 후 연락을 끊고 혼자 있는 시기에는 연결을 유지하고 전문 도움을 빠르게 요청해야 합니다.","cat":"알코올","tags":["알코올","몸·안전"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":46,"q":"술도 끊어야 하고 담배도 끊어야 하는데, 한꺼번에 하면 실패하지 않는가?","a":"금연을 병행한다고 해서 단주가 반드시 실패하는 것은 아닙니다. 두 물질이 서로 촉발요인이 될 수 있으므로 당사자의 준비도와 의료진 의견을 바탕으로 동시 또는 단계적 계획을 세울 수 있습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":47,"q":"갈망을 줄이는 약이 있다는데, 약을 먹으면 술을 끊을 수 있는가?","a":"날트렉손·아캄프로세이트 등은 일부 사람의 갈망과 재발 위험을 줄이는 데 도움이 될 수 있지만 약만으로 회복이 완성되지는 않습니다. 처방약은 심리치료, 모임, 생활계획과 함께 의료진 지도 아래 사용해야 합니다.","cat":"알코올","tags":["알코올","갈망·재발","치료·약물"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":48,"q":"우울증 약과 술을 같이 먹어도 되는가?","a":"술은 여러 정신과 약물의 진정 작용과 부작용을 키우거나 치료 효과를 떨어뜨릴 수 있습니다. 임의로 약을 건너뛰거나 용량을 바꾸지 말고 실제 음주 상황을 처방한 의사나 약사에게 알려야 합니다.","cat":"알코올","tags":["알코올","치료·약물","마음·정서"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":49,"q":"몸이 아직 멀쩡한데 치료가 필요한가?","a":"사용장애는 간수치나 겉으로 보이는 신체 손상만으로 판단하지 않습니다. 조절 실패와 생활 손상이 시작된 단계에서 치료를 시작하면 더 가벼운 개입으로 회복을 도울 기회가 커집니다.","cat":"알코올","tags":["알코올","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":50,"q":"술을 끊으면 몸과 마음은 언제부터 좋아지는가?","a":"급성 금단은 며칠 안에 가라앉을 수 있지만 수면·감정·갈망·관계 회복에는 더 긴 시간이 필요합니다. 몸은 주 단위, 마음과 관계는 월·연 단위로 서로 다른 속도로 좋아질 수 있습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":51,"q":"단주모임에 꼭 나가야 하는가? 병원 치료만으로는 안 되는가?","a":"병원은 진단·약물·치료를, 자조모임은 일상에서 이어지는 동료지지를 제공해 서로 역할이 다릅니다. 모든 사람에게 같은 모임을 강요할 수는 없지만 지속적인 지지체계를 갖는 것은 회복에 도움이 됩니다.","cat":"알코올","tags":["알코올","치료","모임·동료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":52,"q":"12단계는 종교 아닌가? 신앙이 없어도 되는가?","a":"12단계에는 영적 표현이 있지만 특정 종교의 신앙을 강요하는 치료는 아닙니다. 신앙이 없더라도 공동체, 원칙, 자신보다 큰 가치로 이해할 수 있고 다른 근거 기반 치료를 함께 선택할 수도 있습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":53,"q":"본인이 중독자임을 인정하는 것이 왜 그렇게 중요한가?","a":"문제를 인정한다는 것은 낙인을 받아들이는 것이 아니라 도움과 치료가 필요하다는 현실을 받아들이는 과정입니다. 병식은 논쟁으로 강요하기보다 자신의 경험과 결과를 연결하며 서서히 생길 수 있습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":54,"q":"'단주자기효능감'이라는 말을 자주 듣는다. 그것은 무엇이며 어떻게 키우는가?","a":"단주자기효능감은 고위험 상황에서도 마시지 않을 수 있다는 구체적인 믿음입니다. 작은 성공 경험, 우울 치료, 모임과 지지, 현실적인 회피·대처 계획이 이를 키우는 데 도움이 됩니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":55,"q":"오래 단주한 사람들은 도대체 어떻게 버티는가?","a":"장기 회복은 특별한 비법보다 오늘 하루의 선택과 반복되는 일상 구조, 모임과 지지를 유지하는 데서 만들어지는 경우가 많습니다. 좋아졌다 힘들어지는 파동도 회복 과정의 일부로 볼 수 있습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":56,"q":"술을 권하는 자리를 어떻게 넘겨야 하는가?","a":"초기에는 위험한 술자리를 피하는 것이 가장 안전한 전략일 수 있습니다. 가야 한다면 거절 문장, 퇴장 시점, 교통편, 연락할 사람을 미리 정해두는 것이 도움이 됩니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":57,"q":"언제쯤 다시 일을 시작할 수 있는가?","a":"복귀 시점은 단주 기간 하나보다 갈망과 수면이 어느 정도 안정됐는지, 고위험 상황 대처가 가능한지, 외래와 모임 일정을 유지할 수 있는지를 기준으로 보는 편이 좋습니다. 너무 빠른 복귀가 큰 실패 경험이 되지 않도록 단계적으로 준비할 수 있습니다.","cat":"알코올","tags":["알코올","회복생활"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":58,"q":"후원자(스폰서)나 회복 동료가 꼭 있어야 하는가?","a":"모든 사람에게 동일한 형태의 후원자가 필수인 것은 아니지만, 회복 경험을 이해하는 동료와 연결되는 것은 고립을 줄이고 치료를 이어가는 데 도움이 될 수 있습니다. 관계에는 분명한 경계와 상호 존중이 필요합니다.","cat":"알코올","tags":["알코올","모임·동료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":59,"q":"회복에 영성이나 종교가 필요한가?","a":"특정 종교는 필수가 아닙니다. 영성은 통제할 수 없는 것을 인정하고 삶의 의미·공동체·봉사 같은 자신보다 큰 가치와 연결되는 경험으로 이해할 수 있습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":60,"q":"술을 끊으면 삶에서 무엇이 달라지는가?","a":"단주가 쌓이면 삶의 질, 자기존중감, 관계와 사회기능이 회복될 가능성이 커집니다. 회복은 고통이 없어지는 것이 아니라 맑은 정신으로 문제를 다루고 선택할 힘이 돌아오는 과정에 가깝습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":61,"q":"회복 모임에서 만난 사람과 연애를 시작해도 되는가?","a":"회복 초기는 감정과 경계가 아직 불안정할 수 있어 모임 안의 급한 연애가 회복을 흔들 수 있습니다. 특히 권력 차이나 후원 관계가 얽힌 친밀관계는 신중하게 보고, 자신의 치료·모임 지지체계를 우선하는 것이 좋습니다.","cat":"알코올","tags":["알코올","모임·동료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":62,"q":"두 사람 모두 회복자인 커플은 무조건 위험한가?","a":"두 사람이 회복자라는 사실만으로 관계가 나쁜 것은 아닙니다. 서로의 회복을 대신 책임지지 않고 각자의 치료·모임·경계를 유지할 수 있는지가 더 중요한 기준입니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":63,"q":"파트너가 내 회복을 방해하는 것 같다. 그런 일이 실제로 있는가?","a":"파트너의 음주 권유, 모임 방해, 감시·통제, 치료 중단 압력은 회복을 약화시킬 수 있습니다. 반복된다면 개인의 의지 문제로만 보지 말고 관계 안전과 치료 지속 가능성을 상담에서 점검해야 합니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":64,"q":"가스라이팅이라는 말을 들었다. 회복에 어떤 영향을 주는가?","a":"반복적으로 현실 판단을 흔들고 자신을 믿지 못하게 만드는 관계는 치료 선택과 경계 설정을 어렵게 할 수 있습니다. 안전하지 않은 통제나 심리적 폭력이 의심되면 혼자 판단하지 말고 전문가와 구체적인 상황을 확인하는 것이 좋습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":65,"q":"파트너가 술을 권하거나 재발을 유도한다. 이것도 폭력인가?","a":"상대가 회복 중임을 알면서 사용을 강요하거나 치료를 방해하고 위협하는 행동은 심각한 관계 위험 신호입니다. 안전을 우선하고 상담·보호체계와 연결해 반복 패턴을 점검해야 합니다.","cat":"알코올","tags":["알코올","갈망·재발","몸·안전"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":66,"q":"비난과 잔소리가 정말 재발률을 높이는가?","a":"지속적인 비난과 적대적 의사소통은 수치심·은폐와 스트레스를 키워 회복에 불리하게 작용할 수 있습니다. 걱정을 말하되 사람을 공격하기보다 구체적인 행동과 안전·치료 참여를 중심으로 대화하는 편이 낫습니다.","cat":"알코올","tags":["알코올","갈망·재발"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":67,"q":"여성 회복자의 재발은 왜 관계와 더 얽혀 있는가?","a":"여성의 회복 경험에서는 관계 상처, 돌봄 부담, 낙인과 정서적 고립이 재발과 연결되는 경우가 자주 보고됩니다. 술이나 약물만 보지 않고 관계·수면·감정을 함께 관리하는 접근이 필요합니다.","cat":"알코올","tags":["알코올","갈망·재발","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":68,"q":"남성 회복자는 관계 측면에서 무엇이 다른가?","a":"남성 역시 관계가 중요하지만 직장 역할, 감정 표현의 어려움, 사회적 음주 문화 등이 회복을 방해하는 형태로 나타날 수 있습니다. 성별 고정관념보다 개인의 실제 관계 패턴과 도움 요청 방식을 살피는 것이 중요합니다.","cat":"알코올","tags":["알코올","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":69,"q":"그 관계를 끊는 것이 답인가? 헤어지는 것은 회복의 실패 아닌가?","a":"관계를 유지하거나 끝내는 것 자체가 회복의 성공·실패를 결정하지 않습니다. 폭력과 강압이 있으면 안전이 먼저이고, 그 외에는 치료자와 함께 경계·변화 가능성·자신의 회복에 미치는 영향을 기준으로 판단할 수 있습니다.","cat":"알코올","tags":["알코올","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":70,"q":"회복 초기에 관계에서 지켜야 할 원칙은 무엇인가?","a":"회복을 대신 책임질 사람을 만들지 않고 자신의 치료·모임·생활 리듬을 우선하는 것이 중요합니다. 급한 친밀관계나 큰 관계 결정보다 경계를 분명히 하고 안정된 일상을 먼저 만드는 편이 안전합니다.","cat":"알코올","tags":["알코올","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":71,"q":"사람들이 알게 되면 어떻게 하나? 숨기는 것이 나은가?","a":"회복 사실을 모든 사람에게 공개할 의무는 없습니다. 안전과 지지를 기준으로 누구에게 어느 정도 알릴지 선택하고, 치료나 모임 이용을 막을 정도로 숨김이 커지지 않도록 하는 것이 중요합니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":72,"q":"스스로가 한심하게 느껴진다. 이런 자책도 병의 일부인가?","a":"수치심과 자기낙인은 도움 요청을 막고 고립을 키울 수 있습니다. 잘못된 행동에 책임을 지는 것과 자신 전체를 가치 없는 사람으로 보는 것은 다르며, 회복에서는 후자를 줄이는 작업이 필요합니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":73,"q":"술 문제는 개인의 문제인가, 사회의 문제인가?","a":"개인의 취약성뿐 아니라 술에 대한 접근성, 문화, 낙인, 경제·관계 환경이 함께 영향을 줍니다. 개인 치료와 함께 가족·지역사회·정책 수준의 예방과 지원이 필요한 이유입니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":74,"q":"왜 이렇게 치료받는 사람이 적은가?","a":"문제 부인, 낙인과 수치심, 비용·접근성, 치료에 대한 오해가 도움 요청을 늦출 수 있습니다. 증상이 심해지기 전에도 익명 상담, 지역센터, 외래치료 등 낮은 문턱의 지원부터 시작할 수 있습니다.","cat":"알코올","tags":["알코올","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":75,"q":"입원할 정도는 아닌 것 같은데, 그래도 받을 수 있는 도움이 있는가?","a":"입원하지 않아도 외래 진료, 상담, 중독관리통합지원센터, 자조모임과 사례관리 등 여러 지원을 받을 수 있습니다. 오히려 문제가 덜 심할 때 개입하면 일상 기능을 유지하며 치료할 가능성이 커집니다.","cat":"알코올","tags":["알코올","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":76,"q":"사례관리라는 것은 무엇을 해주는가?","a":"사례관리는 치료가 끊기지 않도록 외래, 상담, 복지·주거·직업·가족·지역자원을 연결하고 상황을 함께 점검하는 지원입니다. 대신 살아주는 서비스가 아니라 회복 계획을 실제 생활에서 이어가게 돕는 역할입니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":77,"q":"술 때문에 집과 일자리를 잃었다. 여기서도 회복이 가능한가?","a":"주거와 일자리를 잃은 뒤에도 회복은 가능합니다. 안정된 생활 기반을 다시 만드는 지원과 중독치료를 함께 연결해야 하며, 주거·복지·자활 자원도 치료 계획의 일부가 될 수 있습니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":78,"q":"직장에 알려야 하는가? 회식은 어떻게 하는가?","a":"진단과 치료 사실을 직장 전체에 알릴 필요는 없습니다. 필요한 범위만 선택해 알리고, 회식·접대처럼 고위험 상황은 초기에는 피하거나 거절 문장과 퇴장 계획을 미리 준비하는 것이 좋습니다.","cat":"알코올","tags":["알코올","회복생활"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":79,"q":"다시 일을 하려면 어떤 준비가 필요한가?","a":"수면·체력·갈망이 어느 정도 안정되고 치료 일정과 일을 함께 유지할 수 있어야 합니다. 처음부터 풀타임에 뛰어들기보다 일정과 책임을 단계적으로 늘려가는 방법을 고려할 수 있습니다.","cat":"알코올","tags":["알코올","회복생활"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":80,"q":"회복한 사람도 사회에서 제 역할을 할 수 있는가?","a":"가능합니다. 회복이 안정되면 일, 가족 역할, 동료지원과 지역사회 참여를 다시 만들어갈 수 있으며, 과거의 중독 경험이 다른 사람을 돕는 자원이 되기도 합니다.","cat":"알코올","tags":["알코올"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":81,"q":"도박도 알코올처럼 중독인가?","a":"도박은 물질을 사용하지 않지만 보상과 갈망, 조절력 상실, 생활 손상이라는 점에서 중독 관련 장애로 다뤄집니다. 스마트폰·온라인 환경 때문에 흔적이 적고 발견이 늦을 수 있어 금전·시간·비밀행동의 변화를 함께 봐야 합니다.","cat":"도박","tags":["도박"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":82,"q":"여성 도박자는 남성과 어떻게 다른가?","a":"여성 도박자는 우울·관계 스트레스·돌봄 부담이나 숨김과 낙인이 중독 과정에 강하게 얽히는 경우가 있습니다. 성별만으로 일반화하지 말고 개인의 도박 유형과 관계·정서 촉발요인을 함께 평가해야 합니다.","cat":"도박","tags":["도박"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":83,"q":"빚을 갚아주면 도박을 끊을까?","a":"가족이 반복해서 빚을 대신 갚아주면 당장의 위기는 줄어도 도박의 결과를 당사자가 경험하지 못하게 할 수 있습니다. 안전을 지키되 채무 해결은 전문 재정·법률 상담과 치료계획 속에서 다루는 것이 좋습니다.","cat":"도박","tags":["도박","재정·법률"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":84,"q":"도박도 재발하는가? 어떤 상황에서 다시 하게 되는가?","a":"도박도 재발할 수 있으며 돈 문제만이 아니라 스트레스, 외로움, 무료함, 손실을 되찾으려는 생각, 앱·광고·경기 같은 촉발요인이 영향을 줍니다. 실제 도박 이전의 생각과 행동 변화를 재발 신호로 보는 것이 중요합니다.","cat":"도박","tags":["도박","갈망·재발"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":85,"q":"도박 문제를 가진 배우자와 사는 것은 어떤 일인가?","a":"숨겨진 부채, 반복되는 거짓말과 신뢰 손상이 가족 전체를 불안하게 만들 수 있습니다. 배우자는 재정 안전을 지키면서도 도박을 대신 관리하는 사람으로 고착되지 않도록 가족 상담과 지원을 받을 필요가 있습니다.","cat":"도박","tags":["도박","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":86,"q":"단도박 모임(GA)은 도움이 되는가?","a":"GA 같은 자조모임은 비슷한 경험을 가진 사람과 연결되고 재발 신호와 대처를 지속적으로 점검하는 지지체계가 될 수 있습니다. 한 번의 경험만으로 판단하기보다 자신에게 맞는 모임과 치료를 함께 찾는 것이 좋습니다.","cat":"도박","tags":["도박","모임·동료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":87,"q":"도박 문제가 가족 관계에서 시작되기도 하는가?","a":"가족관계가 도박의 단일 원인은 아니지만 갈등, 외로움, 통제와 경제적 스트레스가 촉발요인이 될 수 있습니다. 가족을 원인으로 탓하기보다 도박과 관계가 서로 영향을 주는 패턴을 함께 다루는 것이 중요합니다.","cat":"도박","tags":["도박","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":88,"q":"마약 문제는 알코올과 무엇이 다른가?","a":"마약류 사용은 물질별 신체 위험과 법적 문제, 강한 낙인이 함께 작용해 도움 요청을 더 어렵게 만들 수 있습니다. 그러나 재발·회복은 정서, 관계, 환경과 치료 지속성이라는 공통 요인을 함께 다뤄야 합니다.","cat":"마약","tags":["마약","치료·약물"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":89,"q":"여성 마약 중독자의 회복은 어떤 과정을 거치는가?","a":"여성에게는 외상, 관계의 강압성, 낙인, 양육과 경제 문제가 치료 접근을 어렵게 할 수 있습니다. 사용 중단만이 아니라 안전, 관계, 생활 기반과 지지체계를 함께 회복하는 계획이 필요합니다.","cat":"마약","tags":["마약","치료·약물"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":90,"q":"여성 마약 중독자가 더 심한 비난을 받는다는 것이 사실인가?","a":"여성 약물사용자는 모성·성역할과 결합된 낙인 때문에 더 숨거나 치료를 미루는 경험을 할 수 있습니다. 비난을 줄이고 안전한 치료·상담 환경을 만드는 것이 조기 개입에 중요합니다.","cat":"마약","tags":["마약","치료·약물"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":91,"q":"자녀가 마약 문제를 겪고 있다. 부모는 어떻게 해야 하는가?","a":"부모가 혼자 감시하고 해결하려 하기보다 안전·과다복용·정신증 위험을 먼저 확인하고 전문 치료·재활과 가족지원을 연결해야 합니다. 돈·주거·법적 문제의 경계도 전문가와 구체적으로 정하는 것이 좋습니다.","cat":"마약","tags":["마약","치료·약물","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":92,"q":"마약 문제도 회복해서 일하고 살아갈 수 있는가?","a":"회복과 사회복귀는 가능합니다. 치료와 재활, 사례관리, 가족·동료 지지, 주거·직업 같은 생활 기반을 함께 회복할수록 일상으로 돌아갈 가능성이 커집니다.","cat":"마약","tags":["마약","치료·약물"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":93,"q":"중독은 왜 자꾸 다른 중독으로 옮겨가는가?","a":"한 행동이나 물질을 끊어도 스트레스·보상추구·감정조절 방식이 그대로 남으면 다른 물질이나 행동으로 옮겨갈 수 있습니다. 회복에서는 특정 대상만 끊기보다 공통 촉발요인과 생활 패턴을 함께 다루는 것이 중요합니다.","cat":"공통","tags":["공통","교차중독","갈망·재발"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":94,"q":"중독마다 회복의 원리가 다른가?","a":"물질별 금단과 치료법은 다르지만, 문제 인정, 안전, 촉발요인 관리, 지지체계, 재발 예방과 생활 회복이라는 큰 원리는 공유합니다. 따라서 공통 원리와 중독별 전문 치료를 함께 적용해야 합니다.","cat":"공통","tags":["공통","회복원리"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":95,"q":"도박 문제는 어떤 치료를 받을 수 있는가?","a":"도박 문제에는 동기강화, 인지행동치료, 재발예방, 가족상담, 재정·법률 지원과 자조모임 등이 활용됩니다. 한국도박문제예방치유원과 지역센터에서 상담·치유·재활 서비스를 받을 수 있습니다.","cat":"도박","tags":["도박","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":96,"q":"아이가 온라인 도박을 하는 것 같다. 어떻게 봐야 하는가?","a":"온라인 도박은 휴대폰으로 숨기기 쉬워 이용시간, 결제·송금, 거짓말, 학업·수면 변화 등을 함께 봐야 합니다. 처벌과 압수만으로 끝내기보다 청소년 도박 전문상담과 가족 개입을 연결하는 것이 좋습니다.","cat":"도박","tags":["도박","가족·자녀","온라인"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":97,"q":"도박 빚 때문에 죽고 싶다고 한다. 어떻게 해야 하는가?","a":"도박 빚과 자살 언급이 함께 나오면 채무 해결보다 생명 안전이 먼저입니다. 혼자 두지 말고 구체적인 자살 위험을 확인해 급하면 109·119·112에 즉시 연결하고, 이후 도박 치료와 재정·법률 지원을 함께 시작해야 합니다.","cat":"도박","tags":["도박","재정·법률","몸·안전"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":98,"q":"마약은 한 번만 해도 끊을 수 없다는 말이 사실인가?","a":"한 번의 사용이 모두에게 곧바로 중독을 만든다고 단정할 수는 없지만, 물질에 따라 과다복용·정신증·의존 위험이 매우 클 수 있습니다. 반복 사용이나 조절 실패가 보이면 빨리 평가와 치료를 받는 것이 중요합니다.","cat":"마약","tags":["마약","치료·약물"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":99,"q":"마약 문제로 처벌을 받게 되면 치료는 못 받는 것인가?","a":"법적 절차와 치료는 서로 배타적이지 않습니다. 마약류 사용자에게도 재활교육, 상담, 치료·회복지원이 제공될 수 있으므로 법률 문제와 별개로 1342나 전문기관을 통해 치료 연결을 확인하는 것이 좋습니다.","cat":"마약","tags":["마약","재정·법률","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":100,"q":"가족이 마지막으로 기억해야 할 것은 무엇인가?","a":"가족이 중독을 대신 멈추게 할 수는 없지만 안전을 지키고 치료 연결을 돕고 자신의 삶을 회복할 수는 있습니다. 환자의 회복과 가족의 회복을 별개의 두 과제로 함께 두는 것이 중요합니다.","cat":"가족","tags":["가족","가족·관계","회복원리"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":101,"q":"나는 그저 가족을 도왔을 뿐인데, 왜 그것이 문제라고 하는가?","a":"도움의 의도와 결과는 다를 수 있습니다. 대신 수습하는 행동이 반복되며 당사자의 책임과 문제 인식을 약화시키는지, 혹은 실제 안전을 지키는 도움인지 결과를 기준으로 구분해야 합니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":102,"q":"조장행동이 공동의존과 어떻게 다른지 모르겠다.","a":"조장행동은 음주·도박·사용의 결과를 대신 처리해 문제를 유지시키는 구체적 행동을 말하고, 공동의존은 상대의 문제를 중심으로 자신의 삶이 조직된 더 넓은 관계 패턴을 뜻합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":103,"q":"술값을 주지 않으면 밖에서 사고를 칠까 봐 결국 주게 된다.","a":"두려움 때문에 술값을 주는 행동은 단기 갈등을 줄여도 사용을 계속 가능하게 할 수 있습니다. 폭력이나 안전 위험은 별도로 보호하고, 돈의 경계는 상담자와 미리 정해 일관되게 적용하는 편이 좋습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":104,"q":"술 때문에 못 나간 날 직장에 대신 전화해 준 적이 있다.","a":"반복해서 결근 사유를 대신 설명하면 음주의 결과를 가족이 떠안게 될 수 있습니다. 안전과 해고 위험 같은 현실 문제를 고려하되, 어디까지 대신할지 상담자와 경계를 정하는 것이 좋습니다.","cat":"가족","tags":["가족","회복생활"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":105,"q":"내가 안 하면 아무도 안 한다는 생각에서 벗어나기 어렵다.","a":"오랫동안 수습 역할을 맡으면 자신이 멈추면 모든 것이 무너질 것처럼 느껴질 수 있습니다. 실제로 안전에 필요한 일과 상대가 책임져야 할 일을 나눠 작은 것부터 내려놓는 연습이 필요합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":106,"q":"언제부터인가 그 사람이 술을 끊는 것이 내 인생의 목표가 되어 있었다.","a":"상대의 단주가 내 삶의 유일한 목표가 되면 내 감정과 생활이 상대의 상태에 종속됩니다. 가족 회복은 '그 사람이 끊어야 내가 산다'에서 벗어나 내 건강과 관계, 일상을 다시 세우는 과정입니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":107,"q":"그 사람의 기분에 따라 내 하루가 정해진다.","a":"상대의 표정과 음주 여부를 계속 확인하는 생활은 만성적인 경계 상태를 만듭니다. 하루의 일부라도 상대와 무관한 계획을 만들고 가족 상담·모임에서 자신의 감정을 따로 다루는 것이 필요합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":108,"q":"우리 집은 어쩌다 이렇게까지 되었는가?","a":"중독이 있는 가정은 한 번의 사건보다 반복되는 사용, 수습, 약속, 실망이 쌓이며 역할과 관계가 변합니다. 원인을 한 사람의 잘못으로 찾기보다 현재 반복되는 고리를 확인하고 하나씩 바꾸는 편이 도움이 됩니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":109,"q":"그 사람은 술을 끊었는데 왜 내가 더 힘들어졌는가?","a":"단주가 시작되면 그동안 위기 대응에 묻혀 있던 가족의 분노·불안·상처가 더 또렷해질 수 있습니다. 환자의 단주와 가족의 회복은 다른 속도로 움직이므로 가족도 별도의 상담과 시간이 필요합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":110,"q":"조장을 멈추면 상황이 더 나빠질까 봐 두렵다.","a":"뒤처리를 줄이면 일시적으로 갈등과 불편이 커질 수 있습니다. 그래서 한꺼번에 끊기보다 위험이 적은 행동부터 줄이고, 폭력·자살·심한 금단은 조장 여부와 관계없이 즉시 개입해야 합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":111,"q":"그 사람에게 분노가 치밀어 오르는 내가 나쁜 사람 같다.","a":"오랫동안 상처와 긴장을 견딘 가족에게 분노는 자연스러운 감정일 수 있습니다. 분노를 없애기보다 안전하게 표현하고 행동으로 폭발하지 않도록 상담·가족모임에서 다루는 것이 중요합니다.","cat":"가족","tags":["가족","마음·정서"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":112,"q":"술에 취한 상태에서는 말이 통하지 않는다. 언제 이야기해야 하는가?","a":"중요한 대화는 취하지 않고 비교적 안정된 시간에 짧게 하는 것이 좋습니다. 취한 상태에서는 설득이나 논쟁보다 안전을 확보하고 필요한 경우 자리를 피하는 것이 우선입니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":113,"q":"이번에는 정말 끊겠다는 말을 몇 번이나 믿어야 하는가?","a":"말의 진정성을 판정하기보다 치료 참여, 외래·모임 지속, 생활 변화처럼 반복되는 행동을 기준으로 보는 편이 현실적입니다. 신뢰는 약속 한 번보다 시간이 쌓이며 다시 만들어집니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":114,"q":"아이가 자꾸 아빠 어디 갔냐고 묻는다. 뭐라고 답해야 하는가?","a":"아이에게 거짓말을 만들기보다 나이에 맞게 '아빠가 몸과 마음이 아파 치료를 받고 있다'고 설명할 수 있습니다. 아이가 자기 탓이라고 느끼지 않도록 분명히 말하고 불안한 감정을 물어봐 주세요.","cat":"가족","tags":["가족","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":115,"q":"시댁에서는 내가 잘하면 된다고 한다.","a":"중독을 배우자의 노력 부족으로 돌리는 말은 가족의 죄책감과 소진을 키울 수 있습니다. 당사자의 치료 책임과 가족의 안전·지원 역할을 구분하고, 필요하면 가족교육 자료를 함께 공유하는 것이 좋습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":116,"q":"같은 집 안에서도 가족마다 대응이 달라 자꾸 싸우게 된다.","a":"한 사람은 막고 다른 사람은 돈을 주는 식으로 대응이 엇갈리면 갈등과 혼란이 커질 수 있습니다. 가족회의나 상담에서 안전·돈·귀가·치료 참여에 대한 최소 원칙을 합의하는 것이 도움이 됩니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":117,"q":"내가 힘들다고 말하면 그 사람이 다시 마실까 봐 말을 못 하겠다.","a":"가족이 감정을 모두 숨기는 것은 장기적으로 관계와 자신의 건강에 부담이 됩니다. 상대의 음주 책임과 내 감정 표현을 분리해, 취하지 않은 시간에 비난 없이 내 상태와 필요한 경계를 말할 수 있습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":118,"q":"왜 아직도 헤어지지 않느냐는 말을 듣는다.","a":"관계를 유지하거나 떠나는 결정은 외부 사람이 단순하게 판단하기 어렵습니다. 안전과 경제·자녀·지지체계 등을 함께 고려하고, 결정 과정 자체를 상담과 법률·복지 지원 속에서 보호받을 필요가 있습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":119,"q":"그 사람이 회복 중인데도 나는 여전히 몰래 확인하게 된다.","a":"오랜 기간의 거짓말과 재발 경험 때문에 경계심이 바로 사라지지 않는 것은 자연스럽습니다. 몰래 감시하는 방식을 계속하기보다 어떤 확인이 필요한지 합의하고, 가족 자신의 불안을 따로 다루는 것이 좋습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":120,"q":"가족모임에 나가려 하면 그 사람이 싫어한다.","a":"가족모임은 환자를 고발하는 자리가 아니라 가족 자신의 회복과 대처를 위한 지원입니다. 상대가 불편해하더라도 가족이 도움받을 권리를 포기할 필요는 없으며, 안전하게 참여할 방법을 상담자와 상의할 수 있습니다.","cat":"가족","tags":["가족","모임·동료","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":121,"q":"밥을 차려주고 옷을 챙겨주는 것도 조장인가?","a":"일상적인 돌봄 자체가 모두 조장은 아닙니다. 그 행동이 상대의 음주·도박·사용 결과를 대신 감당하게 하거나 책임 회피를 가능하게 하는지, 가족의 자발적 돌봄인지 맥락을 보고 판단해야 합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":122,"q":"집안 곳곳에 숨겨둔 술을 찾아내 버린 적이 있다.","a":"술을 치우는 것이 안전에 도움이 되는 상황도 있지만 반복적인 수색과 압수는 가족을 감시자 역할에 묶을 수 있습니다. 금단 위험이 있는 사람에게 갑자기 술을 끊게 하는 것은 위험할 수 있으므로 치료 연결과 함께 계획해야 합니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":123,"q":"덜 마시게 하려고 내가 같이 마셔준 적이 있다.","a":"함께 마시며 양을 조절하려는 방식은 가족에게도 위험하고 상대의 음주를 정상화할 수 있습니다. 음주량 관리를 가족이 맡기보다 치료와 안전 계획에 연결하는 것이 좋습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":124,"q":"차라리 집에서 마시게 하는 편이 안전하지 않은가?","a":"밖에서의 사고를 줄이려는 마음은 이해되지만 집 음주를 관리하는 방식이 장기 치료를 대신할 수는 없습니다. 심한 의존과 금단 위험이 있으면 의료적 해독과 치료계획이 필요합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":125,"q":"끊으면 뭘 사주겠다는 식으로 조건을 걸어도 되는가?","a":"외적 보상이 잠시 동기를 만들 수는 있지만 관계 전체를 거래로 만들거나 약속이 깨질 때 갈등을 키울 수 있습니다. 치료 참여와 작은 변화 자체를 인정하되, 장기 회복은 당사자의 내적 동기와 지지체계가 함께 필요합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":126,"q":"이혼하겠다고 여러 번 말했지만 실행하지 못했다.","a":"지키지 못할 위협이 반복되면 경계의 신뢰가 약해질 수 있습니다. 실제로 실행할 수 있는 작은 경계를 정하고, 큰 결정은 안전·법률·경제 상황을 충분히 검토한 뒤 일관되게 적용하는 편이 좋습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":127,"q":"술 취해 난동을 부릴 때 경찰을 불러도 되는가?","a":"폭력이나 즉각적인 위협이 있으면 가족이 혼자 제압하려 하지 말고 112를 포함한 공적 안전체계를 이용해야 합니다. 경찰을 부르는 것은 처벌을 위한 복수가 아니라 현재의 신체 안전을 확보하는 조치일 수 있습니다.","cat":"가족","tags":["가족","몸·안전"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":128,"q":"본인이 거부해도 강제로 입원시킬 수 있는가?","a":"비자의 입원은 법적·의학적 요건이 엄격하며 가족이 임의로 결정할 수 없습니다. 자·타해 위험이나 심한 정신·금단 증상이 있으면 119·응급실·정신건강 전문기관을 통해 현재 적용 가능한 절차를 확인해야 합니다.","cat":"가족","tags":["가족","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":129,"q":"술을 마신 날은 집에 들어오지 못하게 해도 되는가?","a":"주거 경계는 가족의 안전과 현실 여건에 따라 달라집니다. 술에 취한 사람을 위험한 상태로 밖에 방치하는 결정도 문제가 될 수 있으므로, 폭력·자녀 안전·주거 대안까지 포함해 상담자와 사전 계획을 세우는 것이 좋습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":130,"q":"다 큰 자식의 술 문제를 부모가 언제까지 책임져야 하는가?","a":"성인 자녀의 치료와 선택 책임까지 부모가 대신 질 수는 없습니다. 부모는 안전과 치료 연결을 돕되 돈·빚·생활 결과를 어디까지 지원할지 경계를 정하고 자신의 노후와 건강도 지켜야 합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":131,"q":"내가 먼저 상담을 받으면 그 사람이 배신감을 느끼지 않을까?","a":"가족 상담은 상대를 공격하거나 비밀을 폭로하기 위한 것이 아니라 가족 자신의 건강과 대처를 위한 지원입니다. 당사자가 치료를 거부해도 가족은 먼저 도움을 받을 수 있습니다.","cat":"가족","tags":["가족","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":132,"q":"가족이 먼저 변하면 정말 그 사람도 달라지는가?","a":"가족이 바뀐다고 당사자의 단주가 보장되지는 않습니다. 다만 감시·수습을 줄이고 일관된 경계와 지지를 세우면 가족의 소진을 줄이고 변화가 일어날 수 있는 환경을 만들 수 있습니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":133,"q":"상담에 가면 무엇을 하게 되는가?","a":"가족 상담에서는 중독에 대한 정보, 현재 위험과 대처, 돈·주거·자녀 경계, 가족의 감정과 소진을 함께 살펴봅니다. 환자를 설득하는 비법보다 가족이 통제할 수 있는 부분을 찾는 과정에 가깝습니다.","cat":"가족","tags":["가족","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":134,"q":"처음 참석하는 자리가 두렵다. 무슨 말을 해야 하는가?","a":"처음부터 자신의 모든 이야기를 할 필요는 없습니다. 듣기만 하거나 '처음 왔고 아직 잘 모르겠다'고 말해도 충분하며, 안전하다고 느껴질 때 조금씩 참여할 수 있습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":135,"q":"그동안 참아온 세월이 아깝고 억울하다.","a":"오랜 희생에 대한 억울함은 자연스러운 감정입니다. 지나간 시간을 지우려 하기보다 지금부터 내 삶의 시간과 선택을 되찾는 방향으로 상담과 지지체계를 사용하는 것이 도움이 됩니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":136,"q":"나는 왜 이런 사람을 계속 고르게 되는가?","a":"성장기 관계 경험과 익숙한 돌봄 역할이 이후 관계 선택에 영향을 줄 수 있습니다. 이를 운명이나 안목의 결함으로 보기보다 반복되는 관계 패턴을 상담에서 이해하고 다른 경계를 연습하는 것이 중요합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":137,"q":"어릴 때 우리 집도 이랬는데, 그것과 관련이 있는가?","a":"어린 시절 중독과 갈등 속에서 익힌 역할·경계·감정 표현 방식은 성인 관계에도 영향을 줄 수 있습니다. 과거를 탓하기보다 현재의 선택을 이해하는 자료로 사용하고 필요한 상담을 받을 수 있습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":138,"q":"요즘 두통과 소화불량이 잦은데 병원에서는 이상이 없다고 한다.","a":"만성 스트레스와 불안은 실제 신체 증상으로 나타날 수 있습니다. 반복되는 증상을 무조건 마음 탓으로 넘기지 말고 필요한 의학적 평가를 이어가면서, 스트레스·수면·불안을 함께 다루는 것이 좋습니다.","cat":"가족","tags":["가족","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":139,"q":"내가 좋아하던 일을 다시 시작해도 되는지 죄책감이 든다.","a":"가족이 자신의 취미와 휴식을 되찾는 것은 상대를 버리는 일이 아닙니다. 지속적으로 돌보기 위해서도 자신의 수면, 관계, 즐거움과 생활을 회복하는 시간이 필요합니다.","cat":"가족","tags":["가족","회복생활","마음·정서"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":140,"q":"가족인 나도 회복이 필요하다는 말이 무슨 뜻인가?","a":"가족 회복은 상대의 중독을 멈추게 하는 것이 아니라 오랜 긴장·감시·수습 속에서 잃은 내 삶의 중심과 경계를 되찾는 과정입니다. 환자의 상태와 무관하게 가족 자신의 회복은 시작할 수 있습니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":141,"q":"아이가 어른처럼 집안일을 챙긴다. 기특한 것 아닌가?","a":"위기 가정에서 아이가 지나치게 어른 역할을 맡는 것은 책임감처럼 보이지만 자신의 욕구와 발달을 희생하는 신호일 수 있습니다. 아이에게 어른의 책임을 돌려주고 나이에 맞는 생활과 놀이를 보장해야 합니다.","cat":"가족","tags":["가족","가족·자녀","회복생활"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":142,"q":"아이가 아빠 편을 들며 나를 원망한다.","a":"아이의 편들기는 상황을 단순하게 이해하려는 방식이거나 불안을 줄이기 위한 선택일 수 있습니다. 아이에게 어느 부모 편을 고르게 하지 말고 감정과 안전을 말할 수 있는 자리를 마련하는 것이 중요합니다.","cat":"가족","tags":["가족","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":143,"q":"큰아이는 잘 지내는데 작은아이만 힘들어한다.","a":"같은 집에서 같은 일을 겪어도 아이마다 반응과 보호요인이 다릅니다. 겉으로 잘 지내는 아이도 확인이 필요하고, 더 힘들어하는 아이는 문제행동만 보지 말고 개별 상담과 지지를 연결해야 합니다.","cat":"가족","tags":["가족","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":144,"q":"아이가 술 문제를 밖에서 말할까 봐 걱정된다.","a":"아이에게 가족 비밀을 지키는 책임을 지우면 고립과 수치심이 커질 수 있습니다. 누구에게든 말하라는 뜻은 아니지만 담임·상담교사·친척 등 안전한 어른 한 명에게는 도움을 요청할 수 있게 해주는 것이 좋습니다.","cat":"가족","tags":["가족","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":145,"q":"싸우는 소리를 아이가 다 듣고 있었다.","a":"아이에게는 '네 잘못이 아니다'라고 명확히 말하고, 폭력이나 큰 갈등에서 안전한 공간을 마련해야 합니다. 반복되는 싸움이 있다면 부모 문제만이 아니라 아동의 정서 안전을 위한 전문 지원이 필요합니다.","cat":"가족","tags":["가족","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":146,"q":"아이에게 어른 역할을 시킨 것 같아 미안하다.","a":"죄책감에 머무르기보다 지금부터 아이가 맡아온 어른의 책임을 되돌려받고, 사과와 설명을 통해 관계를 복구할 수 있습니다. 부모가 도움받는 모습을 보여주는 것도 아이에게 중요한 변화입니다.","cat":"가족","tags":["가족","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":147,"q":"장성한 자녀가 그때 왜 지켜주지 않았느냐고 한다.","a":"성인이 된 자녀의 분노와 질문은 뒤늦게 드러난 상처일 수 있습니다. 변명보다 그때의 피해와 감정을 먼저 듣고, 가능한 부분은 책임을 인정하되 관계 회복에는 시간이 필요하다는 점을 받아들여야 합니다.","cat":"가족","tags":["가족","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":148,"q":"손주를 대신 키우고 있는데 내 몸이 버티지 못한다.","a":"손주를 보호하는 일과 돌봄자의 건강을 지키는 일은 함께 가야 합니다. 혼자 버티기보다 가족·복지·지역사회 돌봄자원을 찾아 책임을 나누고 자신의 진료와 휴식도 우선순위에 둬야 합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":149,"q":"아이가 벌써 술이나 담배에 관심을 보인다.","a":"가족력이 있다고 반드시 중독이 되는 것은 아니지만 조기 노출과 스트레스는 위험을 높일 수 있습니다. 겁주기보다 가족력과 위험을 솔직히 설명하고 사용을 감정조절 수단으로 배우지 않도록 대화와 예방교육을 이어가는 것이 좋습니다.","cat":"가족","tags":["가족","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":150,"q":"아이를 데리고 나가야 할지 판단이 서지 않는다.","a":"폭력, 위협, 취중 운전, 방임처럼 아이의 안전이 위험하면 관계 유지보다 보호가 우선입니다. 긴급하면 112·119를 이용하고, 안전계획과 주거·법률·복지 선택은 전문기관과 함께 세우는 것이 좋습니다.","cat":"가족","tags":["가족","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":151,"q":"생활비를 내가 다 대고 있는데 이것도 문제인가?","a":"가족의 생활비 지원 자체가 모두 조장은 아닙니다. 지원이 음주·도박·사용 자금으로 흘러가거나 성인이 책임질 부분을 계속 대신하게 되는지 확인하고, 필수생활비와 현금 지원을 구분하는 방식이 도움이 됩니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":152,"q":"통장과 카드를 내가 관리하는 것이 맞는가?","a":"재정 보호가 필요한 경우 공동 관리나 한도 설정이 도움이 될 수 있지만 강압적인 통제는 갈등을 키울 수 있습니다. 당사자와 합의하고 도박·사용 문제에 대한 치료와 재정상담을 함께 받는 것이 좋습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":153,"q":"빚 독촉 전화가 나에게 온다. 내가 갚아야 하는가?","a":"가족이 법적으로 책임져야 하는 채무인지 먼저 확인해야 하며, 압박 때문에 즉시 대신 갚는 결정은 피하는 것이 좋습니다. 도박·중독 관련 채무는 재정·법률상담을 통해 가족의 책임 범위와 채무조정 방법을 확인할 수 있습니다.","cat":"가족","tags":["가족","재정·법률"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":154,"q":"보증을 서 달라고 한다.","a":"보증은 가족 자신의 재정 안전까지 큰 위험에 놓일 수 있는 결정입니다. 죄책감이나 급박함 속에서 서명하지 말고 독립적인 법률·재정 상담을 받은 뒤 판단해야 합니다.","cat":"가족","tags":["가족","재정·법률"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":155,"q":"집을 팔아서라도 해결해야 하는지 고민이다.","a":"주거 같은 가족의 핵심 안전자산을 처분해 중독 관련 빚을 한 번에 막는 것은 매우 큰 결정입니다. 채무의 성격과 법적 책임, 재발 위험을 전문가와 검토하기 전에는 서두르지 않는 것이 좋습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":156,"q":"내 명의로 대출을 받아준 적이 있다.","a":"이미 대출이 있다면 추가 차입으로 메우기보다 전체 채무와 법적 책임을 정리하고 전문 재정·법률 상담을 받는 것이 좋습니다. 이후에는 내 명의와 신용을 보호할 구체적인 경계를 세워야 합니다.","cat":"가족","tags":["가족","재정·법률"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":157,"q":"경제적으로 독립할 자신이 없어서 못 떠난다.","a":"관계에서 거리를 두고 싶어도 경제 의존이 큰 장벽이 될 수 있습니다. 취업·복지·주거·법률 지원을 하나씩 확인하며 선택지를 늘리는 것이 먼저이며, 폭력이 있다면 경제 준비와 별개로 안전계획이 필요합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":158,"q":"돈 문제로 온 가족이 등을 돌렸다.","a":"반복된 채무와 수습은 가족관계를 크게 소진시킬 수 있습니다. 관계 회복을 서두르기보다 새로운 빚을 만들지 않는 행동, 치료 참여와 재정계획을 지속해 신뢰를 다시 쌓는 과정이 필요합니다.","cat":"가족","tags":["가족","가족·관계","재정·법률"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":159,"q":"치료비가 부담스러워 미루게 된다.","a":"비용 때문에 치료를 포기하기 전 지역 중독센터, 공공상담, 자조모임과 지원제도를 확인해볼 수 있습니다. 필요한 치료 수준과 이용 가능한 무료·저비용 자원을 사회복지사나 사례관리자에게 문의하는 것이 좋습니다.","cat":"가족","tags":["가족","치료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":160,"q":"국가나 지자체에서 받을 수 있는 지원이 있는가?","a":"중독관리통합지원센터, 정신건강복지센터, 도박문제예방치유센터, 함께한걸음센터 등에서 상담·사례관리·재활과 가족지원이 제공될 수 있습니다. 지역과 대상에 따라 지원이 달라지므로 현재 거주지 자원에서 확인하는 것이 정확합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":161,"q":"집에서 나를 환자 취급하는 것이 견디기 힘들다.","a":"회복 중인 사람도 가족 구성원과 한 사람으로서 존중받아야 합니다. 안전과 치료에 필요한 확인을 제외하고 모든 행동을 감시하거나 과거의 중독으로만 해석하는 방식은 관계 회복을 방해할 수 있습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":162,"q":"가족이 다 해주니까 오히려 내가 더 망가진 것 같다.","a":"가족이 결과를 모두 대신 처리하면 당사자가 자기 생활을 다시 책임질 기회가 줄어들 수 있습니다. 회복이 진행될수록 돈, 일정, 집안 역할 같은 책임을 단계적으로 되찾는 과정이 필요합니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":163,"q":"가족에게 미안해서 더 마시게 된다.","a":"죄책감이 술이나 사용으로 이어지는 고리가 생길 수 있습니다. 과거를 한 번에 갚으려 하기보다 오늘의 치료 참여와 안전한 행동으로 책임을 바꾸고, 견디기 힘든 죄책감은 상담에서 직접 다뤄야 합니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":164,"q":"단주를 시작했더니 아내가 오히려 예민해졌다.","a":"가족은 단주가 시작된 뒤에야 그동안 억눌렀던 불안과 분노를 느낄 수 있습니다. 이것이 단주가 잘못됐다는 뜻은 아니며 당사자와 가족이 서로 다른 속도로 회복한다는 점을 이해할 필요가 있습니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":165,"q":"언제까지 내가 증명해야 가족이 믿어주는가?","a":"오랜 기간 손상된 신뢰는 단주 시작과 동시에 회복되지 않습니다. 설명을 반복하기보다 치료·모임·생활 약속을 꾸준히 지키고, 가족이 안전을 확인할 합리적인 기준을 함께 정하는 것이 도움이 됩니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":166,"q":"술을 안 마시니 집에서 내 자리가 없다.","a":"음주 중심으로 굳어진 역할이 사라지면 가족 안에서 어색함과 공백이 생길 수 있습니다. 집안 역할, 대화, 공동 활동을 새로 만들며 '술 없는 나'의 자리를 다시 만들어가는 과정이 필요합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":167,"q":"주변에 아무도 없는데 혼자 힘으로 버틸 수 있는가?","a":"완전히 혼자 버티는 회복은 매우 어렵습니다. 전문치료, 지역센터, 자조모임, 회복동료 등 최소 한두 개의 연결을 만들고 위기 때 연락할 사람과 장소를 미리 정하는 것이 좋습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":168,"q":"내가 가족을 망쳤다는 생각을 견디기 힘들다.","a":"과거 행동에 책임을 느끼는 것과 자신 전체를 파괴적인 사람으로 규정하는 것은 다릅니다. 자책이 너무 커지거나 죽고 싶은 생각으로 이어지면 즉시 의료진·109 등 도움에 연결하고, 회복 행동으로 책임을 바꾸는 것이 중요합니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":169,"q":"아이 얼굴을 볼 면목이 없다.","a":"아이에게 필요한 것은 완벽한 과거가 아니라 지금 안전하고 일관된 부모의 행동입니다. 준비가 되면 변명 없는 사과와 지속적인 회복 행동으로 관계를 다시 만들 수 있습니다.","cat":"가족","tags":["가족","가족·자녀"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":170,"q":"내가 아버지처럼 되어버렸다는 생각이 든다.","a":"가족의 중독 경험이 반복된다는 사실을 알아차리는 것은 변화의 시작이 될 수 있습니다. 닮았다는 이유로 운명처럼 포기하기보다 치료와 관계 패턴 점검을 통해 다른 선택을 만들 수 있습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":171,"q":"명절에 온 친척이 한 잔 권하는 것을 막기 어렵다.","a":"가족 행사 전 당사자와 상의해 가까운 가족 한 사람이 '치료 중이라 술을 권하지 말아 달라'고 미리 알리는 것이 부담을 줄일 수 있습니다. 술 없는 음료와 퇴장 계획도 함께 준비하면 좋습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":172,"q":"집에 있으면 더 마시고 싶어진다.","a":"집 자체가 과거 음주 시간·장소·감정과 연결된 촉발 자극일 수 있습니다. 위험한 시간에 산책·모임·운동 같은 바깥 일정을 만들고 집 안의 술과 음주 단서를 정리하는 것이 도움이 됩니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":173,"q":"회복 동료들과만 어울리려 한다.","a":"회복 초기에는 안전한 동료관계가 큰 보호요인이 될 수 있습니다. 다만 시간이 지나며 가족·직장·취미 관계도 조금씩 회복해 생활 전체가 회복 공동체 하나에만 의존하지 않도록 균형을 넓혀갈 수 있습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":174,"q":"집보다 모임에 있을 때 마음이 놓인다.","a":"모임이 안전하게 느껴지는 것은 자연스럽고 중요한 보호요인입니다. 동시에 집에서도 회복을 지지하는 대화와 역할을 만들 수 있도록 가족 상담이나 작은 공동 활동을 시도해볼 수 있습니다.","cat":"가족","tags":["가족","모임·동료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":175,"q":"언제 다시 마실지 몰라 늘 불안하다.","a":"재발을 완전히 예측할 수 없다는 불안은 가족에게 흔합니다. 모든 순간을 감시하기보다 재발 신호, 위험 시 연락처, 가족의 경계를 미리 정해 '모르면 감시한다'에서 '신호가 오면 계획대로 움직인다'로 바꾸는 것이 도움이 됩니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":176,"q":"갈망이 올라올 때 가족에게 말해도 되는가?","a":"안전하게 말할 수 있는 가족이라면 갈망을 숨기지 않는 것이 재발 예방에 도움이 될 수 있습니다. 가족은 '왜 아직 그러냐'보다 말해준 것을 인정하고, 함께 5분 버티기·모임·상담 연결 같은 다음 행동을 선택하는 편이 좋습니다.","cat":"가족","tags":["가족","갈망·재발","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":177,"q":"나도 이제 그만 돌보고 싶다는 생각이 든다.","a":"돌봄 피로와 '그만하고 싶다'는 마음은 소진의 신호일 수 있습니다. 가족이 모든 지원을 혼자 맡지 말고 역할을 나누고, 자신의 상담·휴식·건강을 우선할 권리가 있습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":178,"q":"나도 가족에게 화가 날 때가 있다.","a":"회복 중인 사람에게도 가족에 대한 분노가 생길 수 있습니다. 화를 술이나 폭력으로 처리하지 않고 시간을 두고 사실·감정·요청을 나눠 말하는 방법을 배우는 것이 관계 회복의 일부입니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":179,"q":"약을 안 먹는 것 같은데 확인해야 하는가?","a":"복약은 치료의 중요한 부분일 수 있지만 몰래 세거나 강압적으로 감시하는 방식은 관계를 해칠 수 있습니다. 부작용이나 거부 이유를 먼저 묻고, 합의된 범위에서 복약을 확인하며 의료진과 상의하는 것이 좋습니다.","cat":"가족","tags":["가족","치료·약물"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":180,"q":"아내는 만나기만 하면 술 이야기만 한다.","a":"가족에게는 여전히 안전과 신뢰가 가장 큰 관심일 수 있습니다. 회복에 필요한 확인 시간을 따로 정하고 그 외 시간에는 일·취미·아이·일상 같은 다른 이야기를 의식적으로 회복하는 것이 관계에 도움이 됩니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":181,"q":"그 사람은 회복했다는데 나는 아직 마음이 풀리지 않는다.","a":"당사자의 단주와 가족의 상처 회복은 같은 속도로 진행되지 않습니다. 용서를 서두르거나 강요하지 말고, 안전과 신뢰가 실제 행동으로 쌓이는 시간을 가족 자신에게도 허용해야 합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":182,"q":"사과해도 소용이 없는 것 같다.","a":"사과 한 번으로 오랜 상처가 없어지지는 않습니다. 변명 없는 사과 뒤에 약속을 지키는 행동과 상대가 말할 준비가 될 때까지 기다리는 태도가 함께 있어야 신뢰가 조금씩 돌아옵니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":183,"q":"자꾸 옛날 일을 꺼내는 내가 문제인가?","a":"과거 이야기가 반복되는 것은 상처가 아직 정리되지 않았다는 신호일 수 있습니다. 모든 갈등 때마다 무기로 쓰는 것은 도움이 되지 않지만, 안전한 상담 자리에서 충분히 다루고 의미를 정리하는 과정은 필요합니다.","cat":"가족","tags":["가족","회복생활"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":184,"q":"지난 일을 계속 듣는 것이 힘들다.","a":"회복 당사자에게 가족의 상처 이야기는 죄책감과 수치심을 자극할 수 있습니다. 회피하거나 방어만 하기보다 들을 수 있는 시간과 한계를 정하고, 감당하기 어려운 부분은 부부·가족상담의 도움을 받을 수 있습니다.","cat":"가족","tags":["가족","회복생활"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":185,"q":"부부 사이가 예전으로 돌아가지 않는다.","a":"회복된 관계는 과거 관계를 그대로 복원하는 것보다 새로운 관계를 만드는 과정에 가깝습니다. 신뢰, 성생활, 돈, 역할과 대화를 하나씩 다시 협상해야 할 수 있습니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":186,"q":"술을 끊고 나니 오히려 외로움이 크다.","a":"술자리가 사라지면 사람과 시간을 함께 잃은 느낌이 들 수 있습니다. 모임, 운동, 취미, 봉사와 같은 술 없는 관계와 즐거움을 새로 만드는 것이 장기 회복의 중요한 부분입니다.","cat":"가족","tags":["가족","마음·정서"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":187,"q":"이제 무슨 이야기를 하며 살아야 할지 모르겠다.","a":"오랫동안 대화의 대부분이 술과 문제수습이었다면 단주 뒤에 공백이 생길 수 있습니다. 식사, 산책, 아이, 취미 같은 작은 일상 주제를 다시 만드는 것부터 관계의 새로운 언어가 시작됩니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":188,"q":"회복 말고 다른 이야기를 하고 싶다.","a":"회복을 지키는 대화가 필요하지만 삶 전체가 중독 이야기만으로 채워질 필요는 없습니다. 치료 확인 시간을 분리하고 나머지 시간에는 일상과 미래, 즐거움에 관한 대화를 회복하는 것이 좋습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":189,"q":"저 사람은 술 없이 사는 법을 모르는 것 같다.","a":"술이 여가·친교·수면·감정조절의 대부분을 맡았던 사람은 단주 뒤 무엇을 해야 할지 모를 수 있습니다. 술 없는 저녁 루틴과 사람, 취미를 실제 일정으로 하나씩 채우는 연습이 필요합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":190,"q":"즐거운 일이 하나도 없다.","a":"회복 초기에 무기력과 즐거움 저하가 나타날 수 있고 우울과도 구분이 필요합니다. 작은 활동을 규칙적으로 시도하되 오래 지속되거나 죽고 싶은 생각이 동반되면 의료진에게 반드시 알려야 합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":true},{"id":191,"q":"형제들은 남의 일처럼 여긴다.","a":"가족마다 경험한 부담과 거리감이 달라 같은 수준의 참여를 기대하기 어렵습니다. 최소한의 안전·연락 역할을 구체적으로 요청하고, 응하지 않는 가족을 설득하는 데 모든 힘을 쓰지 않는 것이 좋습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":192,"q":"친척들이 나를 없는 사람 취급한다.","a":"중독에 대한 낙인 때문에 가족과 당사자가 관계에서 배제되는 경험을 할 수 있습니다. 모든 사람의 이해를 얻으려 하기보다 안전하고 존중하는 사람과 관계를 유지하고, 낙인으로 인한 상처를 상담에서 다룰 수 있습니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":193,"q":"연로하신 부모님이 아직도 이 문제로 괴로워하신다.","a":"고령 부모가 성인 자녀의 중독을 끝까지 책임지다 건강과 노후를 잃을 수 있습니다. 치료 연결은 돕되 돈·주거·돌봄의 한계를 정하고 부모 자신의 건강과 지원체계를 우선해야 합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":194,"q":"부모님께 진 빚을 어떻게 갚아야 할지 모르겠다.","a":"과거를 한 번에 보상하려 하기보다 오늘의 단주·치료·약속 이행처럼 지속 가능한 행동으로 책임을 보여주는 편이 현실적입니다. 부모의 용서 속도는 통제할 수 없다는 점도 받아들여야 합니다.","cat":"가족","tags":["가족","재정·법률"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":195,"q":"이 일이 언제쯤 끝나는가?","a":"회복은 특정 날짜에 모두 끝나는 사건이라기보다 관리가 점점 일상에 녹아드는 과정입니다. 위기와 감시의 비중은 줄어들 수 있지만 당사자와 가족 모두 자신에게 필요한 지지체계를 적절히 유지하는 것이 중요합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":196,"q":"평생 조심하며 살아야 한다는 것이 막막하다.","a":"평생을 한꺼번에 생각하면 회복이 감당하기 어렵게 느껴질 수 있습니다. 오늘 하루와 가까운 계획에 집중하고, 시간이 지나면 회복 관리가 특별한 일이 아니라 생활 습관이 될 수 있다는 점을 기억하는 것이 도움이 됩니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":197,"q":"가족모임을 몇 년째 다니는데 언제까지 다녀야 하는가?","a":"모임을 몇 년 다녔다는 이유로 반드시 끝내야 하는 시점이 정해져 있지는 않습니다. 현재 모임이 나의 경계와 삶을 유지하는 데 어떤 역할을 하는지 보고 빈도와 참여 방식을 조정할 수 있습니다.","cat":"가족","tags":["가족","모임·동료","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":198,"q":"모임에 안 나가도 되는 때가 오는가?","a":"모임을 줄일 수는 있지만 '이제 완전히 괜찮다'는 시험으로 갑자기 끊기보다 다른 지지체계가 충분한지 점검하며 단계적으로 결정하는 편이 안전합니다. 중단 후 상태가 흔들리면 다시 돌아갈 수 있습니다.","cat":"가족","tags":["가족","모임·동료"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":199,"q":"우리 가족의 경험이 누군가에게 도움이 될 수 있는가?","a":"자신의 경험을 안전하게 정리한 뒤 다른 가족을 듣고 지지하는 활동은 경험을 의미 있는 자원으로 바꾸는 과정이 될 수 있습니다. 다만 타인의 위기까지 떠안지 않도록 자신의 회복과 경계를 먼저 지켜야 합니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":200,"q":"회복이 끝나는 지점이 있기는 한가?","a":"회복은 '완전히 끝났다'는 선언보다 중독이 삶의 중심에서 점점 멀어지고 건강한 생활이 일상이 되는 과정으로 이해하는 편이 현실적입니다. 관리의 강도는 줄어들 수 있지만 자신에게 필요한 지지와 안전계획은 필요할 때 다시 사용할 수 있어야 합니다.","cat":"가족","tags":["가족"],"origin":"중독 200문답 v3.8","supplement":false,"urgent":false},{"id":201,"q":"도박에서 잃은 돈을 다시 따려고 하는 마음이 왜 위험한가?","a":"손실을 만회하려 더 큰 돈을 거는 '손실 추격'은 손실과 판단 왜곡을 확대하는 대표적인 도박 위험 패턴입니다. 지금 멈추는 것이 손실을 확정하는 것이 아니라 추가 손실을 막는 행동이라는 관점 전환이 필요합니다.","cat":"도박","tags":["도박","재정·법률"],"origin":"한국도박문제예방치유원","supplement":true,"urgent":false},{"id":202,"q":"온라인 도박 앱과 사이트 접근을 줄이는 현실적인 방법이 있는가?","a":"접근성을 낮추는 것은 의지 부족이 아니라 재발 예방 환경을 만드는 일입니다. 결제수단·한도·도박 계정·광고 알림을 정리하고, 고위험 시간에는 혼자 스마트폰을 오래 쓰지 않도록 대안 일정을 만드는 방식이 도움이 될 수 있습니다.","cat":"도박","tags":["도박"],"origin":"한국도박문제예방치유원","supplement":true,"urgent":false},{"id":203,"q":"도박 빚은 치료와 별개로 먼저 갚아야 하는가?","a":"빚을 급히 막기 위해 새 대출이나 가족 자산을 투입하면 치료 없이 채무만 반복될 수 있습니다. 도박 치료와 함께 채무의 법적 책임, 채무조정, 재정 보호 계획을 전문 재정·법률 상담에서 동시에 다루는 것이 좋습니다.","cat":"도박","tags":["도박","치료","재정·법률"],"origin":"한국도박문제예방치유원","supplement":true,"urgent":false},{"id":204,"q":"주식이나 코인도 도박처럼 문제가 될 수 있는가?","a":"투자 자체와 도박은 같지 않지만 손실을 만회하려 계속 베팅하고, 빚을 내고, 생활을 포기하며 가격 변동에 집착하는 패턴은 도박적 행동과 비슷한 위험을 보일 수 있습니다. 이름보다 통제력과 생활 손상을 기준으로 점검하는 것이 중요합니다.","cat":"도박","tags":["도박"],"origin":"한국도박문제예방치유원·임상적 보완","supplement":true,"urgent":false},{"id":205,"q":"도박을 끊으면 심심하고 아무것도 재미없다. 어떻게 해야 하나?","a":"도박이 강한 자극과 긴장을 반복 제공해 왔다면 평범한 활동이 한동안 밋밋하게 느껴질 수 있습니다. 치유 프로그램에서 여가활동 개발과 새로운 삶의 의미를 별도 과제로 다루는 이유이며, 작은 대안활동을 규칙적으로 반복하는 것이 중요합니다.","cat":"도박","tags":["도박"],"origin":"한국도박문제예방치유원","supplement":true,"urgent":false},{"id":206,"q":"도박 문제 상담은 비용이 많이 드나?","a":"한국도박문제예방치유원은 당사자와 가족에게 상담·치유·재활서비스를 제공하며 공식 안내상 전문상담 서비스는 무료로 이용할 수 있습니다. 지역센터와 1336을 통해 현재 이용 가능한 서비스를 확인할 수 있습니다.","cat":"도박","tags":["도박","치료"],"origin":"한국도박문제예방치유원","supplement":true,"urgent":false},{"id":207,"q":"도박 재발은 실제로 돈을 걸었을 때부터 시작되는가?","a":"재발은 돈을 거는 순간보다 앞서 스트레스, 부인, 도박 생각 증가, 계획·치료 회피 같은 경고 신호에서 시작될 수 있습니다. 신호 단계에서 상담·자가실천·접근 차단을 다시 강화하는 것이 중요합니다.","cat":"도박","tags":["도박","갈망·재발","재정·법률"],"origin":"한국도박문제예방치유원","supplement":true,"urgent":false},{"id":208,"q":"도박 회복에서 가족이 돈을 관리하면 충분한가?","a":"금전 접근을 줄이는 것은 보호조치가 될 수 있지만 그것만으로 도박의 스트레스·생각·관계 문제까지 치료되지는 않습니다. 재정 안전과 함께 개인상담, 가족상담, 재발예방과 대안활동을 병행해야 합니다.","cat":"도박","tags":["도박","가족·관계","재정·법률"],"origin":"한국도박문제예방치유원","supplement":true,"urgent":false},{"id":209,"q":"오피오이드 계열 약물을 끊었다가 다시 사용하면 왜 과다복용 위험이 커질 수 있는가?","a":"특히 오피오이드 계열은 사용을 중단하는 동안 내성이 낮아질 수 있어 이전과 같은 양을 다시 사용하면 과다복용 위험이 커집니다. 재사용 뒤 의식저하·호흡곤란이 있으면 즉시 119가 우선이며, 가능한 한 빨리 치료에 다시 연결해야 합니다.","cat":"마약","tags":["마약","치료·약물"],"origin":"NIDA","supplement":true,"urgent":true},{"id":210,"q":"약물을 여러 종류 함께 쓰는 것이 왜 더 위험한가?","a":"여러 물질을 함께 사용하면 진정·흥분·심장·호흡에 미치는 효과가 예측하기 어려워지고 과다복용 위험이 커질 수 있습니다. 의식이 깨지 않거나 호흡이 느리거나 이상하면 즉시 119에 연락해야 합니다.","cat":"마약","tags":["마약","치료·약물"],"origin":"NIDA/SAMHSA","supplement":true,"urgent":true},{"id":211,"q":"약물 금단은 집에서 혼자 버텨도 되는가?","a":"금단의 위험도는 물질과 사용량, 동반질환에 따라 크게 다릅니다. 스스로 판단해 갑자기 중단하기보다 의료진이 위험을 평가하게 하고, 심한 혼란·경련·호흡 문제·자살 위험이 있으면 응급치료를 받아야 합니다.","cat":"마약","tags":["마약","몸·안전","치료·약물"],"origin":"SAMHSA·임상적 보완","supplement":true,"urgent":true},{"id":212,"q":"마약류 중독은 상담만 받으면 되는가, 의료치료도 필요한가?","a":"물질에 따라 약물치료가 중요한 경우가 있고 정신건강·신체 합병증 평가도 필요할 수 있습니다. 상담·재활과 의료치료를 경쟁 관계로 보지 말고 개인 상태에 맞게 함께 구성하는 것이 좋습니다.","cat":"마약","tags":["마약","치료","치료·약물"],"origin":"SAMHSA/NIDA","supplement":true,"urgent":false},{"id":213,"q":"마약류 문제로 어디에 먼저 전화하면 되는가?","a":"한국마약퇴치운동본부의 함께한걸음센터는 마약류 사용자와 가족을 대상으로 상담·재활·가족지원·자원연계를 제공하며 1342로 문의할 수 있습니다. 응급한 의식저하·호흡곤란·경련은 상담전화보다 119가 먼저입니다.","cat":"마약","tags":["마약","치료·약물"],"origin":"한국마약퇴치운동본부","supplement":true,"urgent":true},{"id":214,"q":"마약류 회복에서 가족지원도 받을 수 있는가?","a":"함께한걸음센터는 당사자뿐 아니라 가족을 대상으로 가족지원 프로그램과 모임을 제공한다고 안내합니다. 가족 역시 돈·주거·연락·안전에 대한 경계를 혼자 정하지 말고 지원을 받을 수 있습니다.","cat":"마약","tags":["마약","치료·약물","가족·관계"],"origin":"한국마약퇴치운동본부","supplement":true,"urgent":false},{"id":215,"q":"마약류 사용 후 환각이나 심한 의심이 생기면 어떻게 해야 하나?","a":"약물 사용 뒤 환각, 심한 피해의식, 통제가 어려운 흥분이 나타나면 논쟁으로 설득하기보다 주변 위험물을 치우고 거리를 확보해야 합니다. 자·타해 위험이나 심한 혼란이 있으면 112·119 등 응급체계를 이용해야 합니다.","cat":"마약","tags":["마약","치료·약물"],"origin":"NIDA/SAMHSA·안전 보완","supplement":true,"urgent":true},{"id":216,"q":"약물 회복 중 다시 사용했으면 치료가 실패한 것인가?","a":"재사용은 치료 전체의 실패가 아니라 치료계획을 다시 점검해야 한다는 신호일 수 있습니다. 특히 내성 저하로 과다복용 위험이 커질 수 있으므로 숨기지 말고 가능한 한 빨리 치료·상담에 복귀하는 것이 중요합니다.","cat":"마약","tags":["마약","치료","치료·약물"],"origin":"NIDA","supplement":true,"urgent":false},{"id":217,"q":"중독과 우울·불안이 함께 있으면 무엇을 먼저 치료해야 하나?","a":"중독과 우울·불안은 서로 악화시킬 수 있어 한쪽이 끝날 때까지 다른 쪽을 미루기보다 함께 평가하고 통합적으로 치료하는 것이 좋습니다. 자살 생각이나 심한 불안·정신증은 즉시 의료진에게 알려야 합니다.","cat":"공통","tags":["공통","치료","마음·정서"],"origin":"NIAAA/SAMHSA","supplement":true,"urgent":true},{"id":218,"q":"회복 중 잠이 무너질 때 술이나 약으로 잠을 재우면 안 되나?","a":"술이나 처방되지 않은 약으로 수면을 해결하면 새로운 의존과 재발 위험을 만들 수 있습니다. 수면 문제는 생활 리듬과 안전한 치료로 따로 다루고, 처방약은 의료진 지시에 따라 사용해야 합니다.","cat":"공통","tags":["공통","치료·약물","몸·생활"],"origin":"NIAAA/SAMHSA","supplement":true,"urgent":false},{"id":219,"q":"회복에서 동료지원이 왜 중요한가?","a":"비슷한 경험을 한 동료는 고립을 줄이고 치료·회복 활동에 계속 참여하도록 도울 수 있습니다. 동료지원은 전문치료를 대신하지 않지만 일상에서 회복을 이어가는 중요한 지지축이 될 수 있습니다.","cat":"공통","tags":["공통"],"origin":"SAMHSA","supplement":true,"urgent":false},{"id":220,"q":"회복계획에 꼭 들어가야 할 것은 무엇인가?","a":"내 촉발요인, 위험 신호, 바로 할 행동, 연락할 사람·기관, 치료·모임 일정, 응급 시 109·119·112 연결을 미리 적어두는 것이 좋습니다. 계획은 위기 때 생각이 흐려져도 따라갈 수 있을 만큼 단순해야 합니다.","cat":"공통","tags":["공통"],"origin":"SAMHSA·앱 보완","supplement":true,"urgent":true},{"id":221,"q":"치료나 모임을 그만두고 싶을 때 무엇을 확인해야 하나?","a":"중단 이유가 안정 때문인지, 지루함·수치심·갈등·재발 전 신호 때문인지 먼저 구분하는 것이 좋습니다. 갑자기 모두 끊기보다 담당자와 빈도를 조정하고 대체 지지체계가 있는지 확인하는 편이 안전합니다.","cat":"공통","tags":["공통","치료","모임·동료"],"origin":"SAMHSA","supplement":true,"urgent":false},{"id":222,"q":"회복 중 즐거움과 의미를 다시 만드는 것도 치료인가?","a":"회복은 사용을 멈추는 것만 아니라 건강, 관계, 일상과 의미를 다시 만드는 과정입니다. 술·도박·약물이 맡았던 시간을 사람·취미·운동·봉사 같은 지속 가능한 활동으로 채우는 것도 회복의 핵심입니다.","cat":"공통","tags":["공통","치료"],"origin":"SAMHSA·한국도박문제예방치유원","supplement":true,"urgent":false},{"id":223,"q":"가족이 지쳐서 더는 도울 수 없을 때는 어떻게 해야 하나?","a":"가족지원은 무한한 책임이 아닙니다. 가족 자신의 건강과 안전을 우선하고 역할을 다른 가족·기관과 나누며, 가족모임·상담을 통해 할 수 있는 것과 내려놓을 것을 정해야 합니다.","cat":"가족","tags":["가족","가족·관계"],"origin":"SAMHSA","supplement":true,"urgent":false},{"id":224,"q":"어떤 증상이면 Q&A를 읽기보다 바로 도움을 요청해야 하나?","a":"경련·환각·심한 혼란·의식저하·호흡곤란, 즉각적인 자해·자살·타해 위험, 폭력이 있으면 정보 검색보다 119·109·112 등 즉시 도움 연결이 먼저입니다. 안전이 확보된 뒤 Q&A와 치료 정보를 활용하세요.","cat":"공통","tags":["공통"],"origin":"안전 보완","supplement":true,"urgent":true}];
